"""CI templates that build a KB's site and publish it to GitHub Pages or GitLab Pages."""

from __future__ import annotations

from pathlib import Path

DEFAULT_INSTALL = "openshelf[site] @ git+https://github.com/hexsecs/openshelf"

GITHUB = """\
# Publishes this OpenShelf KB to GitHub Pages. Generated by `openshelf pages github`.
# One-time setup: Settings → Pages → Build and deployment → Source: "GitHub Actions".
name: Publish KB site

on:
  push:
    branches: [{branch}]
  workflow_dispatch:

permissions:
  contents: read
  pages: write
  id-token: write

concurrency:
  group: pages
  cancel-in-progress: false

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: "3.12"
      - run: pip install "{install}"
      - run: openshelf lint {kb}
      - run: openshelf build {kb} --out _site
      - uses: actions/configure-pages@v5
      - uses: actions/upload-pages-artifact@v3
        with:
          path: _site

  deploy:
    needs: build
    runs-on: ubuntu-latest
    environment:
      name: github-pages
      url: ${{{{ steps.deployment.outputs.page_url }}}}
    steps:
      - id: deployment
        uses: actions/deploy-pages@v4
"""

GITLAB = """\
# Publishes this OpenShelf KB to GitLab Pages. Generated by `openshelf pages gitlab`.
pages:
  image: python:3.12
  script:
    - pip install "{install}"
    - openshelf lint {kb}
    - openshelf build {kb} --out public
  artifacts:
    paths:
      - public
  rules:
    - if: $CI_COMMIT_BRANCH == "{branch}"
"""

TARGETS = {
    "github": (".github/workflows/openshelf-pages.yml", GITHUB),
    "gitlab": (".gitlab-ci.yml", GITLAB),
}


def _quote(path: str) -> str:
    return f"'{path}'" if any(c in path for c in " #:'\"") else path


def write_pages_config(host: str, repo: str | Path, *, kb: str = ".", branch: str = "main",
                       install: str = DEFAULT_INSTALL, force: bool = False) -> Path:
    """Write the CI file for `host` into the repository at `repo`; return its path."""
    rel, template = TARGETS[host]
    dest = Path(repo) / rel
    if dest.exists() and not force:
        raise FileExistsError(f"{dest} already exists; pass --force to replace it, or merge the job in by hand")
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(template.format(kb=_quote(kb), branch=branch, install=install), encoding="utf-8")
    return dest
